package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import com.northstarbank.console.integration.TierClient;import com.northstarbank.console.security.AuthorizationService;import java.math.BigDecimal;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class FinancialService{private final FinancialRepository repo;private final PolicyRepository policy;private final TierClient tiers;private final AuthorizationService auth;private final AuditService audit;private final NotificationRepository notifications;public FinancialService(FinancialRepository r,PolicyRepository p,TierClient t,AuthorizationService a,AuditService l,NotificationRepository n){repo=r;policy=p;tiers=t;auth=a;audit=l;notifications=n;}
 private static final com.fasterxml.jackson.databind.ObjectMapper DRAFTS=new com.fasterxml.jackson.databind.ObjectMapper();static{DRAFTS.activateDefaultTyping(com.fasterxml.jackson.databind.jsontype.impl.LaissezFaireSubTypeValidator.instance,com.fasterxml.jackson.databind.ObjectMapper.DefaultTyping.NON_FINAL);}
 @Transactional public int importDrafts(String customerId,String branch,String payload)throws Exception{auth.require("FINANCIAL_RAISE",branch,false);Object parsed=DRAFTS.readValue(payload,Object.class);if(!(parsed instanceof java.util.List<?> list))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No drafts supplied");int count=0;for(Object entry:list){var m=(java.util.Map<?,?>)entry;raise(String.valueOf(m.get("kind")),customerId,branch,new java.math.BigDecimal(String.valueOf(m.get("amount"))),String.valueOf(m.get("justification")),Boolean.TRUE.equals(m.get("preAuthorized")));count++;}return count;}
   private static final com.github.jknack.handlebars.Handlebars NOTICE=new com.github.jknack.handlebars.Handlebars();
  private String renderNotice(BigDecimal amount){String source=policy.findById(1L).map(p->p.noticeTemplate).orElse(null);if(source==null)return"Approval pending: "+amount+" GBP";try{return NOTICE.compileInline(source).apply(java.util.Map.of("amount",amount,"currency","GBP"));}catch(java.io.IOException e){throw new IllegalStateException(e);}}
  @Transactional public FinancialRequest raise(String kind,String customerId,String branch,BigDecimal amount,String why,boolean preAuthorized){var d=auth.require("FINANCIAL_RAISE",branch,false);BigDecimal ceiling=policy.findById(1L).orElseThrow().policyCeiling;if(amount.signum()<=0||amount.compareTo(ceiling)>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Amount exceeds policy");
  var r=new FinancialRequest(UUID.randomUUID().toString(),kind,customerId,amount,why,auth.user().employeeId(),branch,preAuthorized);
  repo.save(r);if(r.preAuthorized||!d.role().equals("CSR")&&amount.compareTo(d.actAloneThreshold())<=0){transition(r,"approved",null,"below_threshold");apply(r);}else{transition(r,"pending_approval",null,"above_threshold");notifications.save(new Notification("approvers",renderNotice(amount),"/approvals"));}return r;}
 @Transactional public void approve(String id){var r=repo.findById(id).orElseThrow();var d=auth.require("FINANCIAL_APPROVE",r.owningBranch,false,r.requester);if(!r.status.equals("pending_approval")||r.requester.equals(auth.user().employeeId())||r.amount.compareTo(d.approvalLimit())>0||r.amount.compareTo(policy.findById(1L).orElseThrow().policyCeiling)>0)throw new ResponseStatusException(HttpStatus.FORBIDDEN);r.approver=auth.user().employeeId();transition(r,"approved",r.approver,"approver:"+r.approver);apply(r);}
 private void apply(FinancialRequest r){if(r.coreReference!=null)return;var p=tiers.post(auth.user().token(),r.id,r.kind,r.customerId,r.amount);r.coreReference=p.coreReference();transition(r,"applied",r.approver,r.authorizationBasis);}
 private void transition(FinancialRequest r,String to,String approver,String basis){String from=r.status;r.status=to;r.authorizationBasis=basis;audit.record("FINANCIAL_"+to.toUpperCase(),"financial_request",1,r.customerId,basis,from,to);}
 @Transactional public void discard(String id){var r=repo.findById(id).orElseThrow();auth.require("FINANCIAL_APPROVE",r.owningBranch,false);audit.record("FINANCIAL_DISCARDED","financial_request",1,r.customerId,"approver:"+auth.user().employeeId(),r.status,"discarded");
  repo.delete(r);}
 public List<FinancialRequest> pending(){auth.require("FINANCIAL_APPROVE",null,false);return repo.findTop50ByStatusOrderByRequestedAtAsc("pending_approval");}
}
